    from ..session_monitor import get_active_monitor  # Lazy:

    session_id = session_lifecycle.resolve_session_id(window_id)
    if not session_id:
        return None
    monitor = get_active_monitor()
    if monitor is None:
        return None
    return monitor.get_last_activity(session_id)

